#!/bin/bash
# Runs ON EACH HOST as isucon after `task deploy BRANCH=...` (git fetch + reset --hard origin/<branch>).
# Generated by tools/bootstrap/deploy-init.sh from etc/systemd/system/isuride-go.service — edit freely.
set -eu
cd "$(dirname "$0")"
export PATH=$HOME/local/go/bin:$HOME/local/golang/bin:$HOME/go/bin:/usr/local/go/bin:$HOME/.cargo/bin:$PATH
for d in $HOME/local/*/bin; do [ -d "$d" ] && PATH=$d:$PATH; done   # the AMI puts toolchains under ~/local/<name>/bin
CONFIGURED=1
HOST=$(hostname)
echo "== deploy on $HOST: $(git rev-parse --abbrev-ref HEAD)@$(git rev-parse --short HEAD)"

# etc_install <repo path under etc/> : copy to /<path> keeping the original mode/owner recorded in etc/MODES.txt
# (never plain-copy config files: a 640 root file breaks tools the app user runs, e.g. pdnsutil)
etc_install() {
  local src="$1" dst="/$1" m
  m=$(grep " $dst$" etc/MODES.txt 2>/dev/null | head -1)
  sudo install -D -m "${m%% *}" -o "$(echo "$m" | cut -d' ' -f2)" -g "$(echo "$m" | cut -d' ' -f3)" "$src" "$dst" 2>/dev/null \
    || sudo install -D -m 644 -o root -g root "$src" "$dst"
}
# tcp_ok <host> <port> : true when something listens there (checked before restarting the app so a dead DB fails loudly)
tcp_ok() { timeout 3 bash -c "</dev/tcp/$1/$2" 2>/dev/null; }

# ---- 0. DB host (fill when the DB moves to svc3; empty = single host). Set by parallel-setup A. ----
DB_HOST="ip-172-31-6-139"         # hostname of the DB host (svc3)
DB_PRIVATE_IP="172.31.6.139"      # what app hosts dial
# per-host DB override: env.db.<hostname>.sh -> /home/isucon/env.db.sh (svc1/svc2 = 172.31.6.139, svc3 = 127.0.0.1),
# loaded after env.sh by the db.conf drop-in (app) and by webapp/sql/init.sh + indexes/apply.sh (/initialize, deploy).
if [ -f "env.db.$HOST.sh" ]; then
  cp "env.db.$HOST.sh" /home/isucon/env.db.sh
else
  rm -f /home/isucon/env.db.sh   # unknown host: fall back to env.sh (local DB)
fi
if [ -f etc/systemd/system/isuride-go.service.d/db.conf ]; then
  etc_install etc/systemd/system/isuride-go.service.d/db.conf && sudo systemctl daemon-reload
fi
if [ -n "$DB_HOST" ] && [ "$HOST" = "$DB_HOST" ]; then
  # remote access: bind-address + grants (the AMI only has isucon@localhost; other hosts get Error 1130 without this)
  [ -f etc/mysql/mysql.conf.d/zz-remote.cnf ] && ! cmp -s etc/mysql/mysql.conf.d/zz-remote.cnf /etc/mysql/mysql.conf.d/zz-remote.cnf && { etc_install etc/mysql/mysql.conf.d/zz-remote.cnf; sudo systemctl restart mysql; }
  [ -f webapp/sql/zz-grant-remote.sql ] && sudo mysql < webapp/sql/zz-grant-remote.sql
  # performance defaults (flush_log_at_trx_commit=2, no binlog, max_connections): see the file's comments
  [ -f etc/mysql/mysql.conf.d/zz-perf.cnf ] && ! cmp -s etc/mysql/mysql.conf.d/zz-perf.cnf /etc/mysql/mysql.conf.d/zz-perf.cnf && { etc_install etc/mysql/mysql.conf.d/zz-perf.cnf; sudo systemctl restart mysql; }
fi
if [ -n "$DB_PRIVATE_IP" ] && [ "$HOST" != "$DB_HOST" ]; then
  tcp_ok "$DB_PRIVATE_IP" 3306 || { echo "!! DB $DB_PRIVATE_IP:3306 unreachable from $HOST (deploy the DB host first: task deploy does; else SG / bind-address)"; exit 1; }
fi
# matcher: with one shared DB, exactly ONE matcher may run (3 matchers = concurrent assignment of the same rides).
# svc1 only; enable/disable persist across reboots.
MATCHER_HOST="ip-172-31-13-138"
# interval 100 ms + app on 127.0.0.1:8080 (etc/systemd/system/isuride-matcher.service.d/interval.conf; the manual lets us change both)
if [ -f etc/systemd/system/isuride-matcher.service.d/interval.conf ]; then
  etc_install etc/systemd/system/isuride-matcher.service.d/interval.conf && sudo systemctl daemon-reload
fi
if [ "$HOST" = "$MATCHER_HOST" ]; then
  sudo systemctl enable isuride-matcher.service && sudo systemctl restart isuride-matcher.service
else
  sudo systemctl disable --now isuride-matcher.service 2>/dev/null || true
fi
# per-host DB settings are NOT written into env.sh (some contests regenerate it at boot): keep them in env.db.sh and
# load it as a second EnvironmentFile via a systemd drop-in (etc/systemd/system/<unit>.d/db.conf); init.sh must source it too.

# ---- 1. build  (unit: isuride-go.service, WorkingDirectory=/home/isucon/webapp/go, ExecStart=/home/isucon/webapp/go/isuride) ----
( cd webapp/go && CGO_ENABLED=0 go build -o isuride -ldflags '-s -w' . )

# ---- 2. configs kept in the repo (etc/ mirrors /etc). Uncomment the lines for files you changed. ----
etc_install etc/nginx/nginx.conf && etc_install etc/nginx/sites-available/isuride.conf && sudo ln -sf /etc/nginx/sites-available/isuride.conf /etc/nginx/sites-enabled/isuride.conf && sudo nginx -t && sudo systemctl reload nginx
# etc_install etc/mysql/mysql.conf.d/zz-isucon.cnf && sudo systemctl restart mysql     # restarting mysql also restarts isuride-go.service (Requires=)
# etc_install etc/sysctl.d/99-isucon.conf && sudo sysctl --system >/dev/null
# per-host settings (DB host etc.) live in /home/isucon/env.sh: keep a copy per host in the repo and pick it here
# [ -f "env.$HOST.sh" ] && cp "env.$HOST.sh" /home/isucon/env.sh

# ---- 2a. reboot safety: keep restarting the app until the DB (possibly on another host) is up ----
# systemd's default start limit (5 starts / 10 s) turns "DB not ready yet" into a permanently failed unit after a reboot.
# The unit itself: Wants= (not Requires=) mysql — with the DB on svc3, a stopped / failed local mysql must not stop the app
# or fail its start at boot (a dependency failure is not retried by Restart=always). A drop-in cannot reset Requires=.
etc_install etc/systemd/system/isuride-go.service
if [ -f etc/systemd/system/isuride-go.service.d/restart.conf ]; then
  etc_install etc/systemd/system/isuride-go.service.d/restart.conf && sudo systemctl daemon-reload
fi

# ---- 2b. indexes: webapp/sql/indexes/*.sql applied idempotently (index groups of parallel-fix only add files there) ----
[ -x webapp/sql/indexes/apply.sh ] && bash webapp/sql/indexes/apply.sh

# ---- 2c. only isuride-go.service may own the app port: the AMI's other language units Require the DB too, so a DB restart or
# a crash-loop lets one of them take :8080 while isuride-go.service restarts (a Go app that ignores ListenAndServe's error then exits
# silently). disable persists across reboots.
for u in isuride-node.service isuride-perl.service isuride-php.service isuride-python.service isuride-ruby.service isuride-rust.service; do
  sudo systemctl disable --now "$u" 2>/dev/null || true
done

# ---- 3. restart ----
sudo systemctl restart isuride-go.service
sleep 1; systemctl is-active isuride-go.service >/dev/null && echo "== isuride-go.service active on $HOST" || { echo "!! isuride-go.service failed on $HOST"; sudo journalctl -u isuride-go.service -n 30 --no-pager; exit 1; }
